// XGBoost base score in log-odds (from model configuration)
static const float BASE_SCORE_LOGIT[NUM_CLASSES] = {
    -1.469541196f,  // wildfire
    -1.837700056f,  // flood
    -1.776097686f,  // storm
    0.190890877f,  // air_quality
};

// ============================================
// Inference Functions (inline for performance)
// ============================================

// Z-score normalization (in-place)
static inline void normalize_features(float *features, int num_features) {
    int n = num_features < NUM_FEATURES ? num_features : NUM_FEATURES;
    for (int i = 0; i < n; i++) {
        features[i] = (features[i] - NORM_MEAN[i]) / NORM_STD[i];
    }
}

// Sigmoid activation
static inline float sigmoid(float x) {
    if (x > 50.0f) return 1.0f;
    if (x < -50.0f) return 0.0f;
    return 1.0f / (1.0f + expf(-x));
}

// Single tree inference (iterative, no recursion)
static inline float xgb_tree_inference(const xgb_tree_t *tree, const float *features) {
    if (tree->num_nodes == 0) return 0.0f;
    int16_t node_idx = 0;
    
    while (node_idx >= 0 && node_idx < tree->num_nodes) {
        const xgb_node_t *node = &tree->nodes[node_idx];
        
        if (node->feature_idx < 0) {
            return node->leaf_value;
        }
        
        if (features[node->feature_idx] < node->threshold) {
            node_idx = node->left_child;
        } else {
            node_idx = node->right_child;
        }
    }
    return 0.0f;
}

// Full model inference for all 4 hazard classes
static inline void xgb_model_inference(
    const float *features_raw,
    float *output_wildfire,
    float *output_flood,
    float *output_storm,
    float *output_air_quality
) {
    // Normalize features
    float features[NUM_FEATURES];
    for (int i = 0; i < NUM_FEATURES; i++) {
        features[i] = features_raw[i];
    }
    normalize_features(features, NUM_FEATURES);

    // wildfire
    float sum_wildfire = BASE_SCORE_LOGIT[0];
    for (int i = 0; i < WILDFIRE_NUM_TREES; i++) {
        sum_wildfire += xgb_tree_inference(WILDFIRE_TREES[i], features);
    }
    float prob_wildfire = sigmoid(sum_wildfire);

    // flood
    float sum_flood = BASE_SCORE_LOGIT[1];
    for (int i = 0; i < FLOOD_NUM_TREES; i++) {
        sum_flood += xgb_tree_inference(FLOOD_TREES[i], features);
    }
    float prob_flood = sigmoid(sum_flood);

    // storm
    float sum_storm = BASE_SCORE_LOGIT[2];
    for (int i = 0; i < STORM_NUM_TREES; i++) {
        sum_storm += xgb_tree_inference(STORM_TREES[i], features);
    }
    float prob_storm = sigmoid(sum_storm);

    // air_quality
    float sum_air_quality = BASE_SCORE_LOGIT[3];
    for (int i = 0; i < AIR_QUALITY_NUM_TREES; i++) {
        sum_air_quality += xgb_tree_inference(AIR_QUALITY_TREES[i], features);
    }
    float prob_air_quality = sigmoid(sum_air_quality);

    *output_wildfire     = prob_wildfire;
    *output_flood        = prob_flood;
    *output_storm        = prob_storm;
    *output_air_quality  = prob_air_quality;
}

